/**
 * emit to subscription queries of type FindPlannedOrder,
 * but only if the id matches
 *
 * @param		entity	PlannedOrder
 */
	protected void emitFindPlannedOrder( PlannedOrder entity ) {
		LOGGER.info("handling emitFindPlannedOrder" );
		
	    queryUpdateEmitter.emit(FindPlannedOrderQuery.class,
	                            query -> query.getFilter().getPlannedOrderId().equals(entity.getPlannedOrderId()),
	                            entity);
	}
	
